private val Context.pipsDataStore by preferencesDataStore("pips_life_session")
private val ACCOUNT_ID = stringPreferencesKey("account_id");private val SESSION_TOKEN = stringPreferencesKey("session_token");private val SERVER = stringPreferencesKey("server")
private val Ink=Color(0xFF071018);private val Panel=Color(0xFF0D1822);private val Raised=Color(0xFF12212D);private val Line=Color(0xFF223541);private val Primary=Color(0xFFF4F8FA);private val Muted=Color(0xFF91A4AF);private val Green=Color(0xFF35D07F);private val Red=Color(0xFFFF5E68);private val Cyan=Color(0xFF28B7D9)
private val Scheme=darkColorScheme(primary=Cyan,secondary=Green,background=Ink,surface=Panel,surfaceVariant=Raised,onBackground=Primary,onSurface=Primary,outline=Line,error=Red)
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App(applicationContext)}}}
@Composable private fun App(context:Context){var tab by remember{mutableStateOf(0)};var session by remember{mutableStateOf<BackendSession?>(null)};val api=remember{BackendApiClient()};LaunchedEffect(Unit){val p=context.pipsDataStore.data.first();val id=p[ACCOUNT_ID];val token=p[SESSION_TOKEN];if(!id.isNullOrBlank()&&!token.isNullOrBlank())session=BackendSession(id,token,p[SERVER].orEmpty())};val nav=listOf("Home" to Icons.Default.Home,"Strategies" to Icons.Default.Tune,"Positions" to Icons.Default.ShowChart,"MT5" to Icons.Default.AccountBalance,"Settings" to Icons.Default.Settings);MaterialTheme(colorScheme=Scheme){Scaffold(containerColor=Ink,bottomBar={NavigationBar(containerColor=Panel){nav.forEachIndexed{i,n->NavigationBarItem(tab==i,{tab=i},{Icon(n.second,n.first)},{Text(n.first,fontSize=10.sp)},colors=NavigationBarItemDefaults.colors(selectedIconColor=Cyan,selectedTextColor=Cyan,unselectedIconColor=Muted,unselectedTextColor=Muted,indicatorColor=Raised))}}}){p->when(tab){0->Home(Modifier.padding(p),api,session);1->Strategies(Modifier.padding(p));2->Positions(Modifier.padding(p),api,session);3->Mt5(Modifier.padding(p),api){s->session=s;context.pipsDataStore.edit{it[ACCOUNT_ID]=s.accountId;it[SESSION_TOKEN]=s.token;it[SERVER]=s.server}};else->Settings(Modifier.padding(p),session)}}}}
@Composable private fun Home(modifier:Modifier,api:BackendApiClient,session:BackendSession?){var state by remember{mutableStateOf<LiveState?>(null)};var bot by remember{mutableStateOf<BotState?>(null)};var message by remember{mutableStateOf(if(session==null)"Connect an MT5 account to activate live data."else"Synchronizing with backend…")};var busy by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val running=bot?.state?.contains("RUN",true)==true;val pulse=rememberInfiniteTransition(label="pulse").animateFloat(1f,if(running)1.08f else 1f,infiniteRepeatable(tween(900),RepeatMode.Reverse),label="pulse");LaunchedEffect(session){if(session==null){state=null;bot=null}else while(true){api.liveState(session).onSuccess{state=it;message="LIVE • MT5 ${it.connectionStatus}"}.onFailure{message=it.message?:"Live data unavailable"};api.botStatus(session).onSuccess{bot=it};delay(3000)}};LazyColumn(modifier.fillMaxSize().background(Ink).padding(horizontal=18.dp),verticalArrangement=Arrangement.spacedBy(14.dp),contentPadding=PaddingValues(top=18.dp,bottom=24.dp)){item{Header(state!=null)};item{Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(22.dp)){Column(Modifier.fillMaxWidth().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("BOT STATUS",color=Muted,fontSize=11.sp,letterSpacing=1.5.sp);Spacer(Modifier.height(10.dp));Box(Modifier.size(90.dp).scale(pulse.value),contentAlignment=Alignment.Center){Box(Modifier.fillMaxSize().border(2.dp,if(running)Green else Line,CircleShape));Box(Modifier.size(60.dp).background(if(running)Green.copy(alpha=.12f)else Raised,CircleShape));Box(Modifier.size(13.dp).background(if(running)Green else Muted,CircleShape))};Spacer(Modifier.height(10.dp));Text(if(running)"RUNNING" else bot?.state?.replace('_',' ')?:"NOT CONNECTED",color=if(running)Green else Primary,fontSize=20.sp,fontWeight=FontWeight.Bold);Text("Strategy 001 • QOF",color=Muted,fontSize=12.sp);Spacer(Modifier.height(16.dp));Button(enabled=session!=null&&!busy,onClick={busy=true;scope.launch{api.botCommand(session!!,if(running)"stop"else"start").onSuccess{bot=it;message=if(it.configured)"Backend runner command accepted"else"Strategy runner is not configured"}.onFailure{message=it.message?:"Bot control unavailable"};busy=false}},modifier=Modifier.fillMaxWidth().height(54.dp),shape=RoundedCornerShape(16.dp),colors=ButtonDefaults.buttonColors(containerColor=if(running)Red else Green,contentColor=Ink)){Text(if(busy)"WORKING…"else if(running)"STOP BOT"else"START BOT",fontWeight=FontWeight.Bold)}}}};item{Section("LIVE ACCOUNT",message)};item{if(state==null)Empty("Connect MT5 from the MT5 tab. Live balance, equity and positions will appear here.")else AccountCard(state!!)};item{Section("ACTIVE POSITIONS","${state?.positions?.size?:0} open")};if(state?.positions?.isNotEmpty()==true)items(state!!.positions){PositionCard(it)}else item{Empty("No live MT5 positions")};item{Section("STRATEGIES","Expandable")};item{Strategy("001","QOF",if(running)"RUNNING"else"PRIMARY • READY",true);Spacer(Modifier.height(8.dp));Strategy("002","Reserved","FUTURE STRATEGY SLOT",false);Spacer(Modifier.height(8.dp));Strategy("003","Reserved","FUTURE STRATEGY SLOT",false)}}}
@Composable private fun Header(connected:Boolean){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("PIPS-LIFE",color=Primary,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("TRADING CONTROL CENTER",color=Muted,fontSize=11.sp,letterSpacing=1.4.sp)};Pill(if(connected)"MT5 LIVE"else"NO MT5")}}
@Composable private fun AccountCard(s:LiveState)=Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("MT5 ${s.login}",color=Primary,fontWeight=FontWeight.Bold);Text(s.server,color=Muted,fontSize=10.sp)};Text(s.connectionStatus,color=if(s.connectionStatus.equals("CONNECTED",true))Green else Cyan,fontSize=10.sp,fontWeight=FontWeight.Bold)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("BALANCE",money(s.balance,s.currency));Metric("EQUITY",money(s.equity,s.currency));Metric("FREE MARGIN",money(s.freeMargin,s.currency))}}}
@Composable private fun PositionCard(p:LivePosition)=Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(p.symbol,color=Primary,fontSize=17.sp,fontWeight=FontWeight.Bold);Text("${p.side} • ${p.volume} lot",color=Cyan,fontSize=11.sp,fontWeight=FontWeight.Bold)};Text(money(p.profit,""),color=if(p.profit>=0)Green else Red,fontSize=17.sp,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("ENTRY",num(p.entry));Metric("CURRENT",num(p.current));Metric("SL",num(p.stopLoss));Metric("TP",num(p.takeProfit))}}}
@Composable private fun Positions(modifier:Modifier,api:BackendApiClient,session:BackendSession?){var state by remember{mutableStateOf<LiveState?>(null)};LaunchedEffect(session){if(session!=null)while(true){api.liveState(session).onSuccess{state=it};delay(3000)}else state=null};LazyColumn(modifier.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("POSITIONS",color=Primary,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Live positions reported by MT5.",color=Muted,fontSize=12.sp)};if(state?.positions?.isNotEmpty()==true)items(state!!.positions){PositionCard(it)}else item{Empty("No live MT5 positions")}}}
@Composable private fun Mt5(modifier:Modifier,api:BackendApiClient,onConnected:(BackendSession)->Unit){val scope=rememberCoroutineScope();var broker by remember{mutableStateOf("")};var login by remember{mutableStateOf("")};var password by remember{mutableStateOf("")};var server by remember{mutableStateOf("")};var servers by remember{mutableStateOf(emptyList<Mt5Server>())};var busy by remember{mutableStateOf(false)};var status by remember{mutableStateOf("Credentials are sent to the backend; password is not stored locally.")};LazyColumn(modifier.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp),contentPadding=PaddingValues(bottom=20.dp)){item{Text("MT5 ACCOUNT",color=Primary,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Actual MetaApi account connection",color=Muted,fontSize=12.sp)};item{Field(broker,{broker=it},"Broker name")};item{Button(enabled=broker.length>=2&&!busy,onClick={busy=true;scope.launch{api.findServers(broker).onSuccess{servers=it;status="Select the exact MT5 server."}.onFailure{status=it.message?:"Server search failed"};busy=false}}){Text(if(busy)"SEARCHING…"else"FIND SERVERS")}};items(servers){s->Card(onClick={server=s.serverName},colors=CardDefaults.cardColors(containerColor=if(server==s.serverName)Raised else Panel),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Text(s.brokerName,color=Muted,fontSize=10.sp);Text(s.serverName,color=Primary,fontWeight=FontWeight.Bold);Text(s.environment.uppercase(),color=Muted,fontSize=9.sp)}}};item{Field(server,{server=it},"MT5 server")};item{Field(login,{login=it},"MT5 account number")};item{OutlinedTextField(password,{password=it},Modifier.fillMaxWidth(),label={Text("MT5 password")},singleLine=true,visualTransformation=PasswordVisualTransformation())};item{Button(enabled=login.isNotBlank()&&password.isNotBlank()&&server.isNotBlank()&&!busy,onClick={busy=true;status="Connecting through backend…";scope.launch{api.connect(login,password,server,broker).onSuccess{s->password="";onConnected(s);status="Account linked. Synchronizing live MT5 state…"}.onFailure{status=it.message?:"MT5 connection failed"};busy=false}},modifier=Modifier.fillMaxWidth().height(52.dp)){Text(if(busy)"CONNECTING…"else"CONNECT MT5 TO BACKEND")}};item{Text(status,color=Muted,fontSize=12.sp)}}}
@Composable private fun Strategies(modifier:Modifier){LazyColumn(modifier.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("STRATEGIES",color=Primary,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Modular slots; Strategy 001 remains protected.",color=Muted,fontSize=12.sp)};item{Strategy("001","QOF","PRIMARY • LIVE READY",true)};item{Strategy("002","Reserved","FUTURE STRATEGY SLOT",false)};item{Strategy("003","Reserved","FUTURE STRATEGY SLOT",false)}}}
@Composable private fun Settings(modifier:Modifier,session:BackendSession?){Column(modifier.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("SETTINGS",color=Primary,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Pips-life 0.2.1 (3)",color=Muted);Text(if(session!=null)"Authenticated MT5 backend session active."else"No MT5 backend session.",color=Muted,fontSize=12.sp);Text("Strategy 001 preserved • Strategy 002/003 reserved",color=Muted,fontSize=12.sp)}}
@Composable private fun Field(v:String,set:(String)->Unit,label:String)=OutlinedTextField(v,set,Modifier.fillMaxWidth(),label={Text(label)},singleLine=true)
@Composable private fun Section(a:String,b:String)=Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(a,color=Primary,fontSize=13.sp,fontWeight=FontWeight.Bold);Text(b,color=Muted,fontSize=10.sp)}
@Composable private fun Empty(t:String)=Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Text(t,color=Muted,fontSize=12.sp,modifier=Modifier.padding(16.dp))}
@Composable private fun Strategy(n:String,name:String,state:String,active:Boolean)=Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(16.dp)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Text(n,color=if(active)Cyan else Muted,fontWeight=FontWeight.Bold,modifier=Modifier.width(40.dp));Column(Modifier.weight(1f)){Text(name,color=Primary,fontWeight=FontWeight.Bold);Text(state,color=if(active)Green else Muted,fontSize=10.sp)};Icon(Icons.Default.ChevronRight,null,tint=Muted)}}
@Composable private fun Metric(a:String,b:String)=Column{Text(a,color=Muted,fontSize=9.sp);Text(b,color=Primary,fontSize=12.sp,fontWeight=FontWeight.SemiBold)}
@Composable private fun Pill(t:String)=Row(Modifier.background(Panel,RoundedCornerShape(50)),verticalAlignment=Alignment.CenterVertically){Box(Modifier.padding(start=10.dp).size(8.dp).background(if(t=="MT5 LIVE")Green else Muted,CircleShape));Text(" $t",color=Muted,fontSize=10.sp,modifier=Modifier.padding(end=10.dp))}
private fun num(v:Double?)=if(v==null||v.isNaN())"—"else String.format(Locale.US,"%.5f",v)
private fun money(v:Double,c:String)=if(v.isNaN())"—"else String.format(Locale.US,"%s%.2f",if(c.isBlank())""else"$c ",v)
